cpp_src = r'''
#include <torch/extension.h>

void cumsum_cuda(at::Tensor input, at::Tensor output, int64_t dim);
'''

cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void cumsum_kernel(const scalar_t* __restrict__ input,
                              scalar_t* __restrict__ output,
                              int64_t outer,
                              int64_t dim_size,
                              int64_t inner) {
    int64_t tid = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t total = outer * inner;
    for (int64_t idx = tid; idx < total; idx += blockDim.x * gridDim.x) {
        int64_t o = idx / inner;          // index in the outer dimensions
        int64_t i = idx % inner;          // index in the inner dimensions
        float acc = 0.0f;
        for (int64_t d = 0; d < dim_size; ++d) {
            // linear offset for element (o, d, i) in the flattened tensor
            int64_t offset = ((o * dim_size) + d) * inner + i;
            float val = __half2float(input[offset]);
            acc += val;
            output[offset] = __float2half(acc);
        }
    }
}

// ----------------------------------------------------------------------
void cumsum_cuda(at::Tensor input, at::Tensor output, int64_t dim) {
    const int threads = 256;
    // compute outer, dim_size, inner based on the requested dimension
    int64_t dim_size = input.size(dim);
    int64_t outer = 1;
    for (int i = 0; i < dim; ++i) {
        outer *= input.size(i);
    }
    int64_t inner = 1;
    for (int i = dim + 1; i < input.dim(); ++i) {
        inner *= input.size(i);
    }
    int64_t blocks = (outer * inner + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "cumsum_cuda", ([&] {
        cumsum_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            outer,
            dim_size,
            inner);
    }));
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel failed: ", cudaGetErrorString(err));
    }
}

// ----------------------------------------------------------------------
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("cumsum_cuda", &cumsum_cuda, "Cumulative sum along a dimension (CUDA, fp16)");
}
'''

# Compile the extension inline
_cumsum = load_inline(name='cumsum_cuda_ext',
                      cpp_sources=cpp_src,
                      cuda_sources=cuda_src,
                      functions=['cumsum_cuda'],
                      verbose=False)

# ----------------------------------------------------------------------
# Autograd Function wrapping the custom CUDA kernel
