    @staticmethod
    def forward(ctx, input, dim):
        output = torch.empty_like(input)
        _cumsum.cumsum_cuda(input, output, dim)
        ctx.dim = dim
        return output

    @staticmethod
    def backward(ctx, grad_output):
        dim = ctx.dim
        # Gradient of cumsum is the reversed cumulative sum of the upstream gradient
        rev = torch.flip(grad_output, dims=[dim])
        grad = torch.cumsum(rev, dim=dim)
        grad_input = torch.flip(grad, dims=[dim])
        return grad_input, None

# ----------------------------------------------------------------------
