    """
    A model that performs a cumulative sum (prefix sum) along a specified dimension,
    using a custom CUDA kernel that operates on float16 tensors.
    """
    def __init__(self, dim):
        super().__init__()
        self.dim = dim

    def forward(self, x):
        if x.dtype != torch.float16:
            raise TypeError("ModelNew expects float16 (torch.half) tensors.")
        return CumsumFunction.apply(x, self.dim)

